import heapq

def match(orders):
    buy_heap = []  # (-price, seq, id)
    sell_heap = []  # (price, seq, id)
    book = {}  # id -> [side, price, qty, seq, active]
    trades = []
    seq = 0

    for o in orders:
        seq += 1
        typ = o[0]

        if typ == 'cancel':
            oid = o[1]
            if oid in book:
                book[oid][4] = False
            continue

        if typ == 'limit':
            _, oid, side, price, qty = o
        elif typ == 'ioc':
            _, oid, side, price, qty = o
        elif typ == 'market':
            _, oid, side, qty = o
            price = None
        else:
            continue

        remaining = qty

        if side == 'buy':
            opp_heap = sell_heap
        else:
            opp_heap = buy_heap

        while remaining > 0 and opp_heap:
            top = opp_heap[0]
            top_id = top[2]

            if top_id not in book or not book[top_id][4]:
                heapq.heappop(opp_heap)
                continue

            rest_price = book[top_id][1]
            rest_qty = book[top_id][2]

            if rest_qty <= 0:
                heapq.heappop(opp_heap)
                continue

            if side == 'buy':
                if price is not None and rest_price > price:
                    break
            else:
                if price is not None and rest_price < price:
                    break

            heapq.heappop(opp_heap)

            trade_qty = min(remaining, rest_qty)

            if side == 'buy':
                trades.append([oid, top_id, rest_price, trade_qty])
            else:
                trades.append([top_id, oid, rest_price, trade_qty])

            remaining -= trade_qty
            book[top_id][2] -= trade_qty

            if book[top_id][2] > 0:
                heapq.heappush(opp_heap, top)
            else:
                book[top_id][4] = False

        if typ == 'limit' and remaining > 0:
            book[oid] = [side, price, remaining, seq, True]
            if side == 'buy':
                heapq.heappush(buy_heap, (-price, seq, oid))
            else:
                heapq.heappush(sell_heap, (price, seq, oid))

    return trades

